// One independent leg. It sleeps, and it returns a payload that does not mention the
// clock: the wall clock is what changes between budgets, so nothing time-dependent may
// reach the output or the legacy/libpetri data comparison would differ on every run.
await new Promise((resolve) => setTimeout(resolve, 2500));
return [{ json: { leg: 'A' } }];

