// Deterministic by construction: Merge in `append` mode concatenates input 0 then
// input 1 whatever order the branches finished in, so this string is the same at
// every budget and under either engine.
const legs = $input.all().map((item) => item.json.leg);
return [{ json: { legs: legs.length, order: legs.join(',') } }];
